import React, { useEffect, useRef, useState, useContext } from "react";
import { AuthContext } from "../Context/AuthContext";

function CanvasBoard({ socket, currentTool }) {
  const canvasRef = useRef(null);
  const ctxRef = useRef(null);
  const { user } = useContext(AuthContext);

  const [drawing, setDrawing] = useState(false);
  const [text, setText] = useState("");
  const [textPosition, setTextPosition] = useState(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight - 80;
    const ctx = canvas.getContext("2d");
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = "black";
    ctx.lineWidth = 2;
    ctx.font = "20px Arial";
    ctxRef.current = ctx;
  }, []);

  useEffect(() => {
    const ctx = ctxRef.current;
    if (!ctx) return;

    if (currentTool === "eraser") {
      ctx.globalCompositeOperation = "destination-out";
      ctx.lineWidth = 16;
    } else {
      ctx.globalCompositeOperation = "source-over";
      ctx.strokeStyle = "black";
      ctx.lineWidth = 2;
    }
  }, [currentTool]);

  const handleCanvasClick = (e) => {
    if (currentTool === "text") {
      const x = e.nativeEvent.offsetX;
      const y = e.nativeEvent.offsetY;
      setTextPosition({ x, y });
    }
  };

  const addTextToCanvas = () => {
    if (!textPosition || !text) return;
    const ctx = ctxRef.current;
    ctx.fillText(text, textPosition.x, textPosition.y);
    socket.emit("addText", { text, x: textPosition.x, y: textPosition.y });
    setText("");
    setTextPosition(null);
  };

  useEffect(() => {
    socket.on("draw", (data) => {
      const ctx = ctxRef.current;
      ctx.beginPath();
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.moveTo(data.x, data.y);

      if (data.tool === "eraser") {
        ctx.globalCompositeOperation = "destination-out";
        ctx.strokeStyle = "rgba(0, 0, 0, 1)";
        ctx.lineWidth = 16;
      } else {
        ctx.globalCompositeOperation = "source-over";
        ctx.strokeStyle = "black";
        ctx.lineWidth = 2;
      }
      ctx.lineTo(data.x, data.y);
      ctx.stroke();
    });

    socket.on("addText", ({ text, x, y }) => {
      const ctx = ctxRef.current;
      ctx.fillText(text, x, y);
    });

    socket.on("clearBoard", () => {
      ctxRef.current.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);
    });
  }, [socket]);

  const startDrawing = (e) => {
    if (user.role === "viewer" || currentTool === "text") return;

    setDrawing(true);
    const ctx = ctxRef.current;
    ctx.beginPath();
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    ctx.moveTo(e.nativeEvent.offsetX, e.nativeEvent.offsetY);
  };

  const draw = (e) => {
    if (!drawing || currentTool === "text") return;

    const ctx = ctxRef.current;
    const { offsetX, offsetY } = e.nativeEvent;

    if (currentTool === "eraser") {
      ctx.globalCompositeOperation = "destination-out";
      ctx.strokeStyle = "rgba(0, 0, 0, 1)";
      ctx.lineWidth = 16;
    } else {
      ctx.globalCompositeOperation = "source-over";
      ctx.strokeStyle = "black";
      ctx.lineWidth = 2;
    }
    ctx.lineTo(offsetX, offsetY);
    ctx.stroke();

    socket.emit("draw", {
      x: offsetX,
      y: offsetY,
      tool: currentTool,
    });
  };

  const stopDrawing = () => {
    setDrawing(false);
    ctxRef.current.closePath();
  };

  return (
    <div>
      <canvas
        ref={canvasRef}
        className="border bg-white"
        onMouseDown={startDrawing}
        onMouseMove={draw}
        onMouseUp={stopDrawing}
        onMouseLeave={stopDrawing}
        onClick={handleCanvasClick}
      />
      {currentTool === "text" && (
        <>
          <input
            type="text"
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Enter text"
          />
          <button onClick={addTextToCanvas} disabled={!text || !textPosition}>
            Add Text
          </button>
        </>
      )}
    </div>
  );
}

export default CanvasBoard;
